(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zza-sj-prepa-med-j6-ide3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zza-sj-prepa-med-j6-ide3\",\n \"titre\": \"Préparation D.E (J) · J6 Médecine IDE3 (même sujet que le J5)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 44,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J5_Medecine_IDE3_Corrige_explique.pdf\",\n   \"sha256\": \"5c04aa53eb4c7ce4c0fa63fd58420b2b3e4eddb440a34b477ead9482699494e9\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Médecine · Prépa D.E J6 (IDE3)\",\n     \"slug\": \"prepa-med-j6-ide3\",\n     \"pages\": \"\",\n     \"count\": 44,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Médecine\",\n     \"source\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le tabagisme est un facteur général de stomatite\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"(explication hors cours du projet) Le tabac agit directement sur la muqueuse buccale : c'est un facteur local (irritation), et non un facteur général (comme le diabète, l'immunodépression ou les carences) de stomatite. La correction nationale de la Prépa DE (les J) retient donc « Faux ».\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le malade est à la diète absolue car souffre de troubles digestifs depuis 2 mois et a du sang dans les selles. Cette phrase est une donnée d'indépendance\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"(explication hors cours du projet) La diète absolue, les troubles digestifs depuis 2 mois et le sang dans les selles sont des manifestations du problème de santé : ce sont des données de dépendance. Une donnée d'indépendance décrit ce que la personne fait encore seule (ex. âge, lieu de vie, mode de vie conservé).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'angor instable apparait progressivement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'angor d'effort évolue sur des mois ou des années, mais il peut s'aggraver brutalement : c'est l'angor instable (ou angor de repos). Il ne s'installe donc pas progressivement.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Angine de poitrine, 5.1 (p. 91-92)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les carcinomes hépatocellulaires sont les cancers primitifs du foie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours définit les cancers primitifs du foie (CPF) comme le carcinome hépatocellulaire, aussi appelé hépatome. Ils représentent la 1re cause de décès par cancer en Afrique noire.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Cancers primitifs du foie, I-Définition (p. 143-144)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le cas suspect de paludisme est un patient chez qui un agent de santé suspecte un paludisme, habituellement à partir d'une anémie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cas suspect (ou présumé) de paludisme est un patient qui présente une fièvre ou un antécédent de fièvre dans les dernières 24 heures, chez qui un agent de santé suspecte un paludisme. Le point de départ est la fièvre, pas l'anémie.\\n\\nSource : DOCUMENTS DE REVISION L3 Médecine, Paludisme, Vrai/Faux n° 10 (p. 20)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un patient vu au niveau périphérique et présentant des symptômes graves de paludisme, doit faire l'objet d'un test de diagnostic rapide immédiat puis référé avec un traitement de pré-transfert\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Au niveau périphérique, devant des symptômes graves de paludisme, il faut faire immédiatement un TDR, puis référer le patient avec un traitement de pré-transfert (artésunate rectal ou injectable, artéméther IM).\\n\\nSource : DOCUMENTS DE REVISION L3 Médecine, Paludisme, QCM n° 3 et n° 16-17 (p. 22-24)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La stomatite érythématopultacée est caractéristique des stomatites virales\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'aspect érythémato-pultacé (rougeur + enduit blanchâtre facilement détachable) n'est pas propre aux virus : on le retrouve aussi dans les atteintes bactériennes (ex. angine érythémato-pultacée à streptocoque). Il n'est donc pas « caractéristique » des stomatites virales, qui donnent plutôt des vésicules et des ulcérations (herpès).\\n\\nSource : COURS DE MALADIES INFECTIEUSES ET PARASITAIRES, Angines érythémateuses et érythémato-pultacées, 4.1 (p. 44-45) — explication partiellement hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le diagnostic infirmier contient un problème de soin infirmier\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'énoncé d'un diagnostic infirmier comprend le problème infirmier (réel ou potentiel), son étiologie (cause) et les signes ou manifestations. Le problème de soin infirmier en fait donc partie.\\n\\nSource : DOCUMENTS DE REVISION L3 Médecine, Démarche de soins, QCM n° 8 (p. 90-91)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'utilisation de préservatif permet d'assurer une prévention secondaire du cancer du col utérin. Cocher la bonne réponse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La prévention primaire du cancer du col repose sur la vaccination anti-HPV ; la prévention secondaire repose sur le dépistage (frottis, test HPV, IVA) des lésions précancéreuses. Le préservatif limite la transmission des IST (prévention de la contamination), il ne relève pas de la prévention secondaire.\\n\\nSource : ONCOLOGIE, Cancer du col de l'utérus, 7.5 Prévention (p. 38-39)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le cancer de la prostate est le cancer le plus fréquent au monde\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon Globocan 2020 cité dans le cours, les cancers les plus fréquents dans le monde sont, dans l'ordre : sein (2,26 millions), poumon (2,21 millions), côlon-rectum (1,93 million), puis prostate (1,41 million). La prostate n'est donc pas le 1er.\\n\\nSource : ONCOLOGIE, 1.3 Quelques chiffres du cancer, Localisations (p. 5)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les hépatomes sont des cancers développés au dépend des éléments cellulaires qui constituent le foie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"C'est la définition du cours : les cancers primitifs du foie, ou carcinome hépatocellulaire, ou hépatomes, sont des cancers développés aux dépens des éléments cellulaires qui constituent le foie.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Cancers primitifs du foie, I-Définition (p. 144)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"KP est âgé de 8 ans et souffre d'une pneumonie. Il a une perturbation des échanges gazeux et respire rapidement. L'objectif de soins de KP est de ramener la fréquence respiratoire entre 40 et 60 cycles par minute\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"(explication hors cours du projet) Une fréquence respiratoire de 40 à 60 cycles/min correspond à la norme du nouveau-né, pas d'un enfant de 8 ans (environ 20 à 30 cycles/min). L'objectif proposé maintiendrait KP en polypnée : il est donc faux.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La voie ostéopériostée est la plus fréquente lors de la pénétration des germes dans le tissu cellulaire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"(explication hors cours du projet) Dans les cellulites (notamment cervico-faciales d'origine dentaire), la porte d'entrée la plus fréquente est la voie dentaire ostéo-périostée : l'infection part de la dent, traverse l'os et le périoste pour atteindre le tissu cellulaire.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez le cancéreux en phase terminal l'ensemble des besoins de Virginia Henderson ne sont pas satisfaits\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En phase terminale, le malade cancéreux est en dépendance pour l'ensemble des besoins fondamentaux (manger, se mouvoir, éliminer, respirer, communiquer…) : d'où l'objet des soins palliatifs, qui visent à soulager la souffrance physique, psychologique, sociale et spirituelle et à préserver la meilleure qualité de vie.\\n\\nSource : GERIATRIE PP L2, Chap. II Soins palliatifs (diapo 19) — explication partiellement hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Si un patient revient pour un nouvel épisode de fièvre après un traitement antipaludique, il doit être soumis à un test de diagnostic rapide\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Après un traitement antipaludique, le TDR peut rester positif plusieurs semaines (persistance de l'antigène même si le parasite est mort) : il ne sert pas à évaluer le traitement. Le patient qui revient avec une fièvre doit être testé par la goutte épaisse ou le frottis sanguin.\\n\\nSource : DOCUMENTS DE REVISION L3 Médecine, Paludisme, Vrai/Faux n° 17 et QCM n° 2 et n° 4 (p. 20-22) — explication partiellement hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le rôle de l'infirmier dans l'hépatite virale repose sur les activités suivantes sauf une ; laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"accueil\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"prise en charge médicale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"prévention\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"prophylaxie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"soins la surveillance du malade\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. prise en charge médicale\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le rôle de l'infirmier dans l'hépatite virale repose sur l'accueil, les soins et la surveillance du malade, la prophylaxie et la prévention. La prise en charge médicale (diagnostic, prescription) relève du médecin : c'est l'intrus.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Rôle de l'infirmier dans les hépatites virales (p. 122)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La confirmation parasitologique par microscopie du paludisme se fait par\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"la goutte épaisse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"le test de diagnostic rapide\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"frottis sanguin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Retenir les deux bonnes réponses\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. la goutte épaisse ; C. frottis sanguin\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"La goutte épaisse et le frottis sanguin (frottis mince) mettent en évidence le plasmodium au microscope. Le TDR détecte des antigènes : ce n'est pas une confirmation par microscopie. Remarque : Dans le sujet, la dernière option « Retenir les deux bonnes réponses » est une consigne et non une réponse.\\n\\nSource : COURS PATHOLOGIES TROPICALES REVISE L1, Paludisme, VI-Diagnostic biologique (p. 51)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes suivants sont des signes physiques du paludisme simple sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"l'hépatomégalie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"le sub-ictère\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"l'herpès labial\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"la pâleur cutanéomuqueuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. l'hépatomégalie\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"(explication hors cours du projet) Le paludisme simple se manifeste à l'examen par une pâleur cutanéo-muqueuse, un sub-ictère, parfois un herpès labial et une splénomégalie. L'hépatomégalie n'est pas retenue comme signe physique du paludisme simple : c'est l'intrus.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes cliniques suivants, lesquels (03) doivent faire évoquer une thrombose veineuse profonde d'un membre inférieur ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"une augmentation de la chaleur locale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"une abolition du pouls\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"un œdème unilatéral du mollet\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"une diminution de la sensibilité superficielle\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"une dilatation veineuse superficielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. une augmentation de la chaleur locale ; C. un œdème unilatéral du mollet ; E. une dilatation veineuse superficielle\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Le cours décrit dans la TVP : un œdème unilatéral du membre atteint (dur, ne prenant pas le godet), une dilatation des veines superficielles et une chaleur locale excessive à la palpation. L'abolition du pouls oriente vers une ischémie artérielle, et la baisse de la sensibilité n'est pas un signe de TVP.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Thrombose veineuse profonde, 4. Examen clinique (p. 73)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes suivants, indiquer le trouble du transit\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1. la mauvaise haleine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2. le reflux gastro-œsophagien\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3. la constipation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3. la constipation\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le cours classe dans les troubles du transit la constipation, la diarrhée et leur alternance. La mauvaise haleine et le reflux gastro-œsophagien sont d'autres signes digestifs, pas des troubles du transit.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Colopathie fonctionnelle, 2.3 Troubles du transit et 3.1 (p. 126)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes suivants sont des signes physiques du paludisme simple sauf deux, lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"la splénomégalie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"l'ictère franc\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"l'herpès labial\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"la pâleur papillaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. l'ictère franc ; D. la pâleur papillaire\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Dans le paludisme simple, on trouve une splénomégalie, un herpès labial, une pâleur et au plus un sub-ictère. Un ictère franc fait partie des signes de gravité, et la « pâleur papillaire » n'est pas un signe du paludisme simple (c'est la pâleur conjonctivale/cutanéo-muqueuse qui est recherchée).\\n\\nSource : COURS DE MALADIES INFECTIEUSES ET PARASITAIRES, Paludisme grave, 4-2-1 (ictère) (p. 85) — explication partiellement hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Choisir parmi les propositions suivantes, celle qui correspond à l'assertion « les cellules susceptibles de conduire à la formation d'un cancer présentent plusieurs particularités »\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elles assurent les fonctions des cellules normales dont elles dérivent\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Elles sont capables de détourner des cellules locales pour s'en nourrir\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elles n'empêchent pas les défenses immunitaires de l'organisme de les attaquer.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Elles sont capables de détourner des cellules locales pour s'en nourrir\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours cite parmi les particularités des cellules cancéreuses : elles sont capables de détourner les cellules locales pour s'en nourrir (néo-angiogenèse). Les deux autres propositions sont l'inverse du cours : elles n'assurent pas les fonctions des cellules d'origine et elles empêchent les défenses immunitaires de les attaquer.\\n\\nSource : ONCOLOGIE, 1.2 Caractéristiques d'une cellule cancéreuse (p. 5)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes suivants, relever les trois qui constituent des critères de gravité du paludisme\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"épistaxis\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"raideur de la nuque\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"acidose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"trismus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Prostration\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. épistaxis ; C. acidose ; E. Prostration\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Critères de gravité du paludisme dans le cours : prostration, saignements spontanés (dont l'épistaxis), acidose métabolique, ainsi que coma, convulsions, hypoglycémie, etc. La raideur de la nuque et le trismus orientent vers d'autres diagnostics (méningite, tétanos).\\n\\nSource : COURS DE MALADIES INFECTIEUSES ET PARASITAIRES, Paludisme grave, 4-2-1 et 4-2-2 (p. 85-86)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant une hépatite, établir le régime alimentaire approprié\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"riche en glucide, en protides et en graisse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"riche en glucide, protides mais pauvre en graisse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"riche en graisse, protides mais pauvre en glucide\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"riche en graisse, glucide mais pauvre en protides\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. riche en glucide, protides mais pauvre en graisse\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours indique d'établir un régime riche en glucides et en protides mais pauvre en graisses, et de supprimer l'alcool.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Rôle de l'infirmier dans les hépatites virales, B-Les soins (p. 123)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un objectif de soin est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"un sujet unique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"une fin que l'on veut atteindre pour le client\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"un idéal pour le malade\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"une recommandation de l'institution de soin.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. une fin que l'on veut atteindre pour le client\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un objectif de soins est le résultat que l'on veut atteindre pour le client (formulé avec un verbe d'action, mesurable et daté). Ce n'est ni un idéal ni une recommandation institutionnelle.\\n\\nSource : DOCUMENTS DE REVISION L3 Médecine, Démarche de soins, QCM n° 9-11 (p. 91) — explication partiellement hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes suivants, relever les troubles digestifs\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1. la constipation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2. le reflux gastro-œsophagien\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3. la dyspepsie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. 2. le reflux gastro-œsophagien ; C. 3. la dyspepsie\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Le cours cite parmi les « autres signes digestifs » le reflux gastro-œsophagien et la dyspepsie. La constipation est classée à part, comme trouble du transit (voir la question 20).\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Colopathie fonctionnelle, 3.1 Éléments d'orientation (p. 126)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant la douleur de péricardite aigue, toutes les propositions suivantes sont justes sauf une. Laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"la douleur s'accentue volontiers lors des mouvements respiratoires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"la douleur peut s'accompagner de troubles du rythme supra-ventriculaires\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'ECG peut montrer des troubles diffus de la repolarisation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La douleur peut s'accompagner d'un frottement péricardique disparaissant en apnée\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le traitement de première intention est une prescription d'Aspégic\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. Le traitement de première intention est une prescription d'Aspégic\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"La douleur de péricardite augmente à l'inspiration et à la toux. L'ECG est perturbé dans toutes les dérivations (repolarisation). Le cours prévoit en traitement repos et antalgique (paracétamol), le reste dépendant de l'étiologie : l'Aspégic n'y figure pas comme traitement de première intention. Remarque : Classiquement, le frottement péricardique persiste en apnée (c'est le frottement pleural qui disparaît). La proposition D est donc elle aussi discutable ; le cours ne précise pas ce point.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Chap. IV La péricardite aiguë (p. 97-99)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes suivants, relever les trois qui constituent des critères de gravité du paludisme\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"hypoglycémie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"cystite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"hyper-parasitémie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"pollakiurie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"œdème pulmonaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. hypoglycémie ; C. hyper-parasitémie ; E. œdème pulmonaire\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Le cours cite comme critères de gravité : hypoglycémie, hyperparasitémie et œdème pulmonaire (radiologique). La cystite et la pollakiurie ne font pas partie des critères de gravité.\\n\\nSource : COURS DE MALADIES INFECTIEUSES ET PARASITAIRES, Paludisme grave, 4-2-1 et 4-2-2 (p. 85-86)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les mesures prophylactiques suivantes face à une hépatite, identifier celle qui protège le personnel médical\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1. Isoler le malade en chambre individuelle durant toute l'hospitalisation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2. Utiliser un matériel à usage unique pour les injections, les prélèvements de sang\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3. désinfecter rigoureusement les mains avant et après chaque soin.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3. désinfecter rigoureusement les mains avant et après chaque soin.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le cours le dit textuellement : « pour le personnel médical, désinfecter rigoureusement les mains avant et après chaque soin ». L'isolement et le matériel à usage unique protègent surtout les autres malades.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Hépatites virales, D-Mesures prophylactiques (p. 123)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'œdème aigu du poumon\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"est souvent lié à une bronchite chronique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"entraine des douleurs du cœur\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"est lié à une défaillance cardiaque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. est lié à une défaillance cardiaque\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'OAP est une insuffisance cardiaque gauche aiguë : les alvéoles sont inondées car le cœur n'arrive plus à pomper suffisamment. Il est donc lié à une défaillance cardiaque, et non à une bronchite chronique.\\n\\nSource : COURS DE SEMIOLOGIE MEDICALE ET PATHOLOGIES RESPIRATOIRES, OAP, I-Définition (p. 60)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"un objectif de soins infirmiers relève de\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"la fin que l'on veut atteindre pour le client.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"l'indépendant du client dans la satisfaction de ses besoins\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"la personne soignée et du diagnostic infirmier\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. la personne soignée et du diagnostic infirmier\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'objectif de soins infirmiers se formule à partir du diagnostic infirmier et est centré sur la personne soignée (« le patient doit être capable de… »). Remarque : La même formule « fin que l'on veut atteindre pour le client » est retenue comme bonne réponse à la question 25. Le document de révision pose cette question sans corrigé.\\n\\nSource : DOCUMENTS DE REVISION L3 Médecine, Démarche de soins, QCM n° 10 (p. 91) — explication partiellement hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le rétrécissement mitral\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"est une complication rare du rhumatisme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"entraine souvent des troubles du rythme cardiaque\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"est presque toujours héréditaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. entraine souvent des troubles du rythme cardiaque\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le rétrécissement mitral, séquelle fréquente du rhumatisme articulaire aigu, dilate l'oreillette gauche et entraîne souvent des troubles du rythme (surtout la fibrillation auriculaire). Il n'est ni rare ni héréditaire.\\n\\nSource : COURS DE MALADIES INFETUEUSES-1, RAA, 2.3 Signes cardiaques (p. 36) — explication partiellement hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Histologiquement, le processus pathologique de la cirrhose associe les stades suivants sauf un ; lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1- une dégénérescence des cellules hépatiques avec surcharge en graisse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2- une régénération envahissante par du tissu conjonctif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3- Un ramollissement hépatique progressif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"4- une sclérose encerclant les formations nodulaires normales.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3- Un ramollissement hépatique progressif\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le cours décrit trois stades histologiques : dégénérescence des cellules hépatiques avec surcharge graisseuse, régénération envahissante par du tissu conjonctif, sclérose encerclant les nodules. Le foie cirrhotique est dur, pas ramolli.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Les cirrhoses, II-Anatomie pathologique (p. 128)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les indications suivantes de l'aspiration duodénale continue figure un intru. Démasquez-le\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1- syndrome de sub-occlusion ou d'occlusion\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2- dans les chirurgies intestinales en dehors d'occlusion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3- lavage d'estomac\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3- lavage d'estomac\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Indications de l'aspiration duodénale continue dans le cours : syndrome de sub-occlusion ou d'occlusion, chirurgies intestinales en dehors d'occlusion (en pré- ou post-opératoire). Le lavage d'estomac relève de l'aspiration gastrique.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Soins infirmiers dans les aspirations digestives, B (p. 141-142)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est l'objectif essentiel d'une démarche de soins\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Permettre la mise en place d'actions de soins adaptées et individualisées à chaque patient.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Assurer les soins et la surveillance des patients placés en isolement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Observer le malade au plan social, médical et comportemental\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Permettre la mise en place d'actions de soins adaptées et individualisées à chaque patient.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La démarche de soins est un processus de résolution de problème centré sur la personne, qui aboutit à une prestation de soins individualisés : son but est d'adapter les actions de soins à chaque patient.\\n\\nSource : DOCUMENTS DE REVISION L3 Médecine, Démarche de soins, QCM n° 1 (p. 89-90)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la cirrhose décompensée, le syndrome œdémato-ascitique est marqué par les signes suivants sauf un ; lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1. Prise de poids,\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2. Augmentation du périmètre abdominal,\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3. Pancréatite\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"4. Météorisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3. Pancréatite\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le syndrome œdémato-ascitique se reconnaît à une prise de poids et à une augmentation du périmètre abdominal, souvent précédées d'un météorisme. La pancréatite n'en fait pas partie.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Les cirrhoses, Syndrome œdémato-ascitique (p. 130)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson GG est âgé de 4 mois. Il vit avec sa mère à Abidjan. GG est à l'allaitement prépondérant. La mère est inquiète car GG est amaigri. Le médecin pense à un début de dénutrition. L'analyse des données du nourrisson GG conclue à\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2 données d'indépendance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3 données d'indépendance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"4 données d'indépendance\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"5 données d'indépendance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 4 données d'indépendance\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"(explication hors cours du projet) Les données d'indépendance de GG sont : l'âge (4 mois), il vit avec sa mère, à Abidjan, et il est à l'allaitement prépondérant, soit 4 données. L'amaigrissement, l'inquiétude de la mère et la suspicion de dénutrition sont des données de dépendance.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les indications suivantes des aspirations digestives figure une contre-indication ; laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1- traitement médical de la perforation de l'estomac\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2- préparation à une intervention gastrique ou abdominale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3- cancers d'estomac\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"4- lavage d'estomac\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3- cancers d'estomac\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le cours cite comme indications : traitement médical de la perforation de l'estomac, préparation à une intervention gastrique ou abdominale, suites d'intervention et lavage d'estomac. La seule contre-indication citée : les cancers de l'estomac.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Aspirations digestives, III-Indication et contre-indication (p. 140-141)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On définit l'insuffisance cardiaque gauche comme étant : (cochez les bonne réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une incapacité du ventricule gauche à assurer un débit sanguin suffisant dans les conditions normales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La non-satisfaction des besoins métaboliques et fonctionnels de l'organisme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une insuffisance de remplissage de sang dans les cavités cardiaques gauche\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Une incapacité du ventricule gauche à assurer un débit sanguin suffisant dans les conditions normales ; B. La non-satisfaction des besoins métaboliques et fonctionnels de l'organisme\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"L'IVG est l'incapacité du ventricule gauche à assurer le débit sanguin nécessaire aux besoins métaboliques et fonctionnels de l'organisme (à l'effort puis au repos). Il ne s'agit pas d'un défaut de remplissage des cavités gauches.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, Chap. II, A. Insuffisance ventriculaire gauche, 1. Définition (p. 85)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes cliniques dans l'insuffisance cardiaque droite sont les signes de stases et se résument à : sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Turgescence des veines jugulaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dyspnée à type de polypnée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Œdème des membres inférieurs\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Dyspnée à type de polypnée\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans l'IVD, les signes de stase en amont sont la turgescence des jugulaires, l'hépatomégalie et les œdèmes des membres inférieurs. La dyspnée est un signe d'aval (mauvaise perfusion pulmonaire), pas un signe de stase.\\n\\nSource : COURS MEDECINE IDE 2 INFAS ACTUALISE 2020, B. Insuffisance ventriculaire droite, 2. Physiopathologie (p. 88)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'œdème aigu du poumon aussi appelé Insuffisance cardiaque gauche est définie comme étant : (Cochez les bonnes réponses parmi ces propositions de réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Obstruction des alvéoles pulmonaires par un thrombus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Inondation des alvéoles pulmonaire C – Fuite du plasma lors de l'hématose\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Excès du liquide présent dans les alvéoles suite à la fuite du plasma se dirige vers le cœur\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Difficulté du poumon à assurer son rôle d'échange gazeux\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Incapacité du cœur à pomper efficacement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Inondation des alvéoles pulmonaire C – Fuite du plasma lors de l'hématose ; C. Excès du liquide présent dans les alvéoles suite à la fuite du plasma se dirige vers le cœur ; E. Incapacité du cœur à pomper efficacement\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Le cours définit l'OAP comme une insuffisance cardiaque gauche aiguë avec inondation des alvéoles par le plasma en excès, qui ne peut revenir assez vite vers le cœur, car celui-ci n'arrive plus à pomper suffisamment. L'obstruction par un thrombus correspond à l'embolie pulmonaire. Remarque : Dans le sujet, les propositions B et C sont réunies sur une même ligne (« B– Inondation… C – Fuite du plasma… »).\\n\\nSource : COURS DE SEMIOLOGIE MEDICALE ET PATHOLOGIES RESPIRATOIRES, OAP, I-Définition (p. 60)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__41\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe pathognomonique de la rougeole est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La fièvre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le catarrhe occulo-nasale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le signe de Koplick\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'éruption cutanée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le signe de Koplick\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le signe de Köplik (petites taches blanches sur fond rouge à la face interne des joues, en regard des prémolaires) est le signe pathognomonique de la rougeole : il confirme le diagnostic dès la phase d'invasion.\\n\\nSource : COURS DE MALADIES INFETUEUSES-1, Rougeole, 3.1.2 Phase d'invasion (p. 25)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'une des complications redoutables du rhumatisme articulaire aigu est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une atteinte articulaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une atteinte cardiaque\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une atteinte rénale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une atteinte cérébrale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une atteinte cardiaque\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'atteinte cardiaque (péricardite, myocardite, endocardite, valvulopathies mitrale ou aortique) est la manifestation la plus grave du RAA : elle peut tuer et elle seule laisse des séquelles graves. L'atteinte articulaire guérit sans séquelles.\\n\\nSource : COURS DE MALADIES INFETUEUSES-1, RAA, 2.3 Signes cardiaques (p. 36)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j6-ide3__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La phase d'état du tétanos est marquée par 02 signes lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le Trismus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La fièvre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La contracture généralisée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les vomissements\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le Trismus ; C. La contracture généralisée\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"La phase d'état du tétanos associe le trismus, la contracture musculaire généralisée et les paroxysmes. Le trismus ne s'accompagne pas de fièvre. Remarque : L'option d n'est pas visible dans la capture (coupure entre deux pages) ; seules a, b, c et e sont reproduites.\\n\\nSource : COURS PATHOLOGIES TROPICALES REVISE L1, Tétanos, II-Étude clinique (p. 74)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Médecine IDE3 (corrigé expliqué) — repris au J6\",\n       \"sourceFile\": \"J5_Medecine_IDE3_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      }\n     ],\n     \"doublonDe\": \"prepa-med-j5-ide3\"\n    }\n   ]\n  }\n ]\n}";
